from pathlib import Path
import numpy as np,pandas as pd
rng=np.random.default_rng(42); idx=pd.bdate_range('2021-01-01',periods=750)
for j,t in enumerate(['AAPL','MSFT','GOOGL','AMZN','NVDA']):
 ret=rng.normal(.00035+j*.00004,.014,len(idx)); close=(100+25*j)*np.cumprod(1+ret); op=close*(1+rng.normal(0,.002,len(idx))); high=np.maximum(op,close)*1.01; low=np.minimum(op,close)*.99; vol=rng.integers(1e6,8e6,len(idx))
 pd.DataFrame({'Open':op,'High':high,'Low':low,'Close':close,'Volume':vol},index=idx).to_csv(Path('data/sample')/f'{t}.csv')
from pathlib import Path
f=Path('src/models/classical_model.py');f.write_text('''"""Logistic regression baseline."""\nimport joblib\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score,precision_score,recall_score,f1_score,roc_auc_score,confusion_matrix\nfrom src.utils.config import ROOT,FEATURES\ndef metrics(y,p,prob):\n d={"accuracy":accuracy_score(y,p),"precision":precision_score(y,p,zero_division=0),"recall":recall_score(y,p,zero_division=0),"f1":f1_score(y,p,zero_division=0),"confusion_matrix":confusion_matrix(y,p).tolist()}\n try:d["roc_auc"]=roc_auc_score(y,prob)\n except ValueError:d["roc_auc"]=float("nan")\n return d\ndef train(x,y,save=True):\n m=make_pipeline(SimpleImputer(strategy="median"),StandardScaler(),LogisticRegression(random_state=42,max_iter=1000));m.fit(x,y)\n if save: (ROOT/"models").mkdir(exist_ok=True);joblib.dump(m,ROOT/"models/classical.joblib")\n return m\nif __name__=="__main__":\n from src.data.loader import load\n from src.features.technical_features import make_features\n from src.data.preprocessing import chronological_split\n d=next(iter(load().values())); f=make_features(d); a,_,c=chronological_split(f);m=train(a[FEATURES],a.target);print(metrics(c.target,m.predict(c[FEATURES]),m.predict_proba(c[FEATURES])[:,1]))\n''',encoding='utf8')
Path('src/models/quantum_model.py').write_text('''"""Four-qubit PennyLane variational classifier."""\nimport numpy as np\ntry: import pennylane as qml\nexcept ImportError: qml=None\nclass QuantumClassifier:\n def __init__(self,layers=2,backend="auto",epochs=20,seed=42,stepsize=.08):\n  if qml is None: raise ImportError("Install pennylane and pennylane-lightning")\n  self.layers=layers;self.epochs=epochs;self.seed=seed;self.backend=backend;self.loss_history=[]\n  name="lightning.qubit" if backend=="auto" else backend\n  try:self.dev=qml.device(name,wires=4);self.backend=name\n  except Exception:self.dev=qml.device("default.qubit",wires=4);self.backend="default.qubit"\n  @qml.qnode(self.dev,interface="autograd")\n  def circuit(x,w):\n   for i in range(4):qml.RY(x[i],wires=i)\n   for k in range(layers):\n    for i in range(4):qml.RY(w[k,i,0],wires=i);qml.RZ(w[k,i,1],wires=i)\n    for i in range(4):qml.CNOT(wires=[i,(i+1)%4])\n   return qml.expval(qml.PauliZ(0))\n  self.circuit=circuit;self.weights=np.random.default_rng(seed).normal(0,.1,(layers,4,2),requires_grad=True)\n def _scale(self,X):\n  X=np.asarray(X,float);return np.pi*np.tanh(X)\n def fit(self,X,y):\n  X=self._scale(X); y=np.asarray(y,float)*2-1; opt=qml.AdamOptimizer(.08)\n  for _ in range(self.epochs):\n   def loss(w):return qml.math.mean(qml.math.stack([(self.circuit(x,w)-t)**2 for x,t in zip(X,y)]))\n   self.weights,l=opt.step_and_cost(loss,self.weights);self.loss_history.append(float(l))\n  return self\n def predict_proba(self,X):\n  z=np.array([float(self.circuit(x,self.weights)) for x in self._scale(X)]);p=np.clip((1-z)/2,0,1);return np.c_[1-p,p]\n def predict(self,X):return (self.predict_proba(X)[:,1]>=.5).astype(int)\nif __name__=="__main__":print("Use run_pipeline.py to train on chronological sample data")\n''',encoding='utf8')
Path('src/portfolio/optimizer.py').write_text('''"""Long-only mean variance portfolio optimizer."""\nimport numpy as np\nfrom scipy.optimize import minimize\ndef optimize(expected_returns,covariance,risk_aversion=5,max_weight=.4):\n mu=np.asarray(expected_returns,float);cov=np.asarray(covariance,float);n=len(mu)\n if n*max_weight<1:raise ValueError("max_weight too small to fully invest")\n def obj(w):return -(w@mu-risk_aversion*(w@cov@w))\n r=minimize(obj,np.ones(n)/n,bounds=[(0,max_weight)]*n,constraints=[{"type":"eq","fun":lambda w:w.sum()-1}],method="SLSQP",options={"maxiter":500,"ftol":1e-12})\n if not r.success:raise ValueError(r.message)\n return r.x\n''',encoding='utf8')
Path('src/portfolio/risk.py').write_text('''import numpy as np\ndef risk_metrics(values,periods=252):\n v=np.asarray(values,float);r=v[1:]/v[:-1]-1 if len(v)>1 else np.array([]);cum=np.cumprod(1+r);peak=np.maximum.accumulate(np.r_[1,cum]);dd=np.r_[1,cum]/peak-1\n ann=(cum[-1]**(periods/len(r))-1) if len(r) else 0;vol=np.std(r,ddof=1)*np.sqrt(periods) if len(r)>1 else 0\n return {"annualized_return":float(ann),"annualized_volatility":float(vol),"sharpe_ratio":float(ann/vol) if vol else 0.,"max_drawdown":float(dd.min()),"cumulative_return":float(cum[-1]-1) if len(r) else 0.,"daily_returns":r}\n''',encoding='utf8')
Path('run_pipeline.py').write_text('''"""Run sample or market data research workflow."""\nimport argparse\nimport numpy as np,pandas as pd\nfrom src.data.loader import load\nfrom src.features.technical_features import make_features\nfrom src.data.preprocessing import chronological_split\nfrom src.models.classical_model import train,metrics\nfrom src.models.quantum_model import QuantumClassifier\nfrom src.utils.config import FEATURES,QUANTUM_FEATURES,ROOT\ndef main():\n ap=argparse.ArgumentParser();ap.add_argument('--mode',choices=['sample','market'],default='sample');ap.add_argument('--epochs',type=int,default=20);args=ap.parse_args();results=ROOT/'results';results.mkdir(exist_ok=True)\n data=load(args.mode);rows=[];models=[]\n for ticker,df in data.items():\n  f=make_features(df);tr,va,te=chronological_split(f);cm=train(tr[FEATURES],tr.target);qm=QuantumClassifier(epochs=args.epochs).fit(tr[QUANTUM_FEATURES],tr.target);\n  for name,m,cols in [('classical',cm,FEATURES),('quantum',qm,QUANTUM_FEATURES)]:\n   pr=m.predict(te[cols]);pb=m.predict_proba(te[cols])[:,1];rows.append({'asset':ticker,'model':name,**metrics(te.target,pr,pb)})\n  models.append((ticker,df,cm,qm,f))\n pd.DataFrame(rows).to_csv(results/'model_comparison.csv',index=False);alloc=[]\n for ticker,df,cm,qm,f in models:\n  latest=f.iloc[-1];prob=float(qm.predict_proba([latest[QUANTUM_FEATURES]])[0,1]);alloc.append({'asset':ticker,'predicted_direction':int(prob>=.5),'prediction_probability':prob,'expected_return':(prob-.5)*.04})\n mu=np.array([x['expected_return'] for x in alloc]);rets=pd.concat([d.Close.pct_change().rename(t) for t,d,*_ in models],axis=1).dropna();from src.portfolio.optimizer import optimize\n w=optimize(mu,rets.cov().values);\n for x,weight in zip(alloc,w):x['portfolio_weight']=weight\n pd.DataFrame(alloc).to_csv(results/'portfolio_allocation.csv',index=False)\n print(pd.DataFrame(rows).to_string(index=False));print(pd.DataFrame(alloc).to_string(index=False))\nif __name__=='__main__':main()\n''',encoding='utf8')
